/// C++: `CNetObj_SwitchState`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ObjSwitchState {
    pub highest_switch_number: i32,
    pub status: [i32; 8],
    pub switch_numbers: [i32; 4],
    pub end_ticks: [i32; 4],
}
impl ObjSwitchState {
    pub const TYPE_ID: i32 = NETOBJTYPE_SWITCHSTATE;
    pub const NUM_INTS: usize = 17;
    pub fn from_ints(d: &[i32]) -> Self {
        let mut s = Self::default();
        s.highest_switch_number = d[0];
        s.status.copy_from_slice(&d[1..9]);
        s.switch_numbers.copy_from_slice(&d[9..13]);
        s.end_ticks.copy_from_slice(&d[13..17]);
        s
    }
    pub fn to_ints(&self) -> Vec<i32> {
        let mut d = Vec::with_capacity(17);
        d.push(self.highest_switch_number);
        d.extend_from_slice(&self.status);
        d.extend_from_slice(&self.switch_numbers);
        d.extend_from_slice(&self.end_ticks);
        d
    }
}

